  const vowel = vowels[Math.floor(nameRandom() * vowels.length)];
  const middle = consonants[Math.floor(nameRandom() * consonants.length)];
  const ending = (vowels + "y")[Math.floor(nameRandom() * (vowels.length + 1))];
