        rhythm: { phase: 0, drive: 0, pace: 0, gliding: false }, time: 0, landed: 0, strain: 0, pull: { x: 0, y: 0, z: 0 },
        arms: [makeLimb("arm", -1, o.arm), makeLimb("arm", 1, o.arm)],
