    springs.tiltV = (springs.tiltV || 0) + 7;
  springs.lastFacing = facing;
  const crouchRate = rig.crouchV || 0;
  if (crouchRate < -3 && player.grounded)
    springs.tiltV = (springs.tiltV || 0) + clamp(-crouchRate * .25, 0, 3);
