  const center=kind==='skirt'?{x:hip.x,y:hip.y-2+u*65,z:hip.z}:{x:lerp(neck.x,hip.x,u),y:lerp(neck.y,hip.y,u)+u*6,z:lerp(neck.z,hip.z,u)};
