 for(let i=0;i<8;i++)for(const bit of [1,2,4])if(!(i&bit)){
  const a=corners[i],b=corners[i|bit];hudWorldLine(a.x,a.y,a.z,b.x,b.y,b.z,3,[255,48,64]);
 }
